css:
@font-face {
    font-family: "THSarabun";
    src: url("{{ frappe.utils.get_url() }}/assets/erpnext_thailand/fonts/THSarabun.ttf") format("truetype");
}

@page { margin: 0; }
/* ปลดล็อค height และ overflow ออกเพื่อให้ขึ้นหน้า 2 ได้ */
html, body { margin: 0; padding: 0; }

.print-format {
    padding: 0 !important;
    margin: 0 !important;
    min-height: unset !important;
    max-width: unset !important;
}

.print-format-preview {
    padding: 0 !important;
}

/* ── Base ── */
.po-bg {
  position: relative;
  width: 210mm;
  height: 280mm;
  background-image: url("/assets/connect_diagnostics_core/images/purchase_orders.webp");
  background-size: 100% 100%;
  background-repeat: no-repeat;
  font-family: 'Sarabun', Arial, sans-serif;
  color: #575858;
  overflow: hidden; /* คำสั่งนี้อยู่ที่กรอบแต่ละหน้าแทน เพื่อไม่ให้ของล้นออกนอกแผ่น */
}
.f { position: absolute; line-height: 1.2; }
.tr { text-align: right; }
.tc { text-align: center; }

.title { top: 42mm; left: 132mm; width: 47mm; font-size: 12pt; }

/* ── Supplier Info ── */
.sup-code { top: 53mm; left: 30mm; width: 91mm; font-size: 8.5pt;}
.sup-name { top: 60mm; left: 18mm; width: 91mm; font-size: 8.5pt; }
.sup-addr { top: 64mm; left: 18mm; width: 91mm; font-size: 8.5pt; }
.sup-mob  { top: 81mm; left: 28mm; font-size: 10pt; }
.sup-conf { top: 88mm; left: 28mm; font-size: 10pt; }

/* ── PO Details ── */
.po-name  { top: 53mm; left: 132mm; font-size: 8.5pt; }
.po-date  { top: 58.5mm; left: 132mm; font-size: 8.5pt; }
.po-sched { top: 70.5mm; left: 132mm; font-size: 8.5pt; }
.po-pay   { top: 75mm; left: 132mm; font-size: 8.5pt; }
.po-inco  { top: 88mm; left: 132mm; width: 70mm; font-size: 10pt; }

/* ── Items (Columns) ── */
.col-idx  { left: 14mm; width: 11mm; font-size: 9pt; }
.col-item { left: 26mm; width: 76mm; font-size: 8.5pt; overflow: hidden; white-space: nowrap; }
.col-wh   { left: 102mm; width: 9mm; font-size: 8pt; }
.col-qty  { left: 120mm; width: 20mm; font-size: 9pt; }
.col-rate { left: 141mm; width: 21mm; font-size: 9pt; }
.col-disc { left: 161mm; width: 15mm; font-size: 9pt; }
.col-amt  { left: 176mm; width: 26mm; font-size: 9pt; }

/* ── Footer / Totals ── */
.rem-terms { top: 232mm; left: 14mm; width: 90mm; font-size: 8.5pt; }
.tot-amt   { top: 215.0mm; left: 176.5mm; width: 26mm; font-size: 9.5pt; }
.tot-disc  { top: 221.0mm; left: 176.5mm; width: 26mm; font-size: 9.5pt; }
.tot-net   { top: 227.0mm; left: 176.5mm; width: 26mm; font-size: 9.5pt; }
.tot-tax   { top: 233.0mm; left: 176.5mm; width: 26mm; font-size: 9.5pt; }
.tot-grand { top: 240.5mm; left: 176.5mm; width: 26mm; font-size: 10pt; }
.tot-words { top: 240.5mm; left: 45mm; width: 83mm; font-size: 9pt; }

html:
{%- set co = frappe.db.get_value("Company", doc.company, ["company_name", "company_logo", "tax_id", "phone_no", "website"], as_dict=True) %}
{%- set print_pages = ['ต้นฉบับ/Original', 'สำเนา/Copy'] %}

{% for page_title in print_pages %}
<div class="po-bg">

  {# ── ข้อความบอกสถานะหน้า (ปรับ top, left ได้ตามตำแหน่งที่ต้องการวาง) ── #}
  <div class="f tc title">{{ page_title }}</div>

  {# ── Supplier Info ── #}
  <div class="f sup-code">{{ doc.supplier}}</div>
  <div class="f sup-name">{{ doc.supplier_name }}</div>
  {%- if doc.address_display %}
  <div class="f sup-addr">{{ doc.address_display }}</div>
  {%- endif %}
  <div class="f sup-mob">{{ doc.contact_mobile or "" }}</div>
  <div class="f sup-conf">{{ doc.order_confirmation_no or "" }}</div>

  {# ── PO Details (right panel) ── #}
  <div class="f po-name">{{ doc.name }}</div>
  <div class="f po-date">
    {%- if doc.transaction_date %}
      {%- set d = (doc.transaction_date|string).split(' ')[0].split('-') -%}
      {{ d[2] }}/{{ d[1] }}/{{ ((d[0]|int)|string)[-4:] }}
    {%- endif %}
  </div>
  
  <div class="f po-sched">
    {%- if doc.schedule_date %}
      {%- set sd = (doc.schedule_date|string).split(' ')[0].split('-') -%}
      {{ sd[2] }}/{{ sd[1] }}/{{ ((sd[0]|int)|string)[-4:] }}
    {%- endif %}
  </div>
  <div class="f po-pay">{{ doc.payment_terms_template or "" }}</div>
  <div class="f po-inco">{{ doc.incoterm or "" }}{%- if doc.named_place %} {{ doc.named_place }}{%- endif %}</div>

  {# ── Items ── #}
  {%- for item in doc.items %}
  {%- set rt = 101.0 + loop.index0 * 8.0 %}
  <div class="f tc col-idx" style="top:{{ '%.1f'|format(rt) }}mm;">{{ loop.index }}</div>
  <div class="f col-item" style="top:{{ '%.1f'|format(rt) }}mm;">
    <span>{{ item.item_code }}: </span>{%- if item.item_name and item.item_name != item.item_code %} {{ item.item_name }}{%- endif %}
  </div>
  <div class="f tc col-wh" style="top:{{ '%.1f'|format(rt) }}mm;">{{ (item.warehouse or "").split(" - ")[0] }}</div>
  <div class="f tr col-qty" style="top:{{ '%.1f'|format(rt) }}mm;">{{ "%g"|format(item.qty) }} {{ item.uom }}</div>
  <div class="f tr col-rate" style="top:{{ '%.1f'|format(rt) }}mm;">{{ frappe.utils.fmt_money(item.rate, currency=doc.currency) }}</div>
  <div class="f tr col-disc" style="top:{{ '%.1f'|format(rt) }}mm;">{{ ("%g"|format(item.discount_percentage)) + "%" if item.discount_percentage else "" }}</div>
  <div class="f tr col-amt" style="top:{{ '%.1f'|format(rt) }}mm;">{{ frappe.utils.fmt_money(item.amount, currency=doc.currency) }}</div>
  {%- endfor %}

  {# ── Remark ── #}
  <div class="f rem-terms">{{ doc.terms or "" }}</div>

  {# ── Totals ── #}
  <div class="f tr tot-amt">{{ frappe.utils.fmt_money(doc.total, currency=doc.currency) }}</div>
  <div class="f tr tot-disc">{{ frappe.utils.fmt_money(doc.discount_amount or 0, currency=doc.currency) }}</div>
  <div class="f tr tot-net">{{ frappe.utils.fmt_money(doc.net_total, currency=doc.currency) }}</div>
  <div class="f tr tot-tax">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges or 0, currency=doc.currency) }}</div>
  <div class="f tr bold tot-grand">{{ frappe.utils.fmt_money(doc.rounded_total or doc.grand_total, currency=doc.currency) }}</div>
  
  {# ── In Words ── #}
  <div class="f tot-words">({{ number_to_thai_currency(doc.grand_total, doc.currency) }}).</div>

</div>

{# ── สั่งให้ขึ้นหน้าใหม่หากยังไม่จบหน้าสุดท้าย ── #}
{% if not loop.last %}
<div style="page-break-after: always;"></div>
{% endif %}

{% endfor %}
